GRAMMAR_TOPICS=[g(*x) for x in [("pronouns","Personal pronouns","Use ང, ཁྱེད་རང and ཁོ in basic statements.",["ང་སློབ་མ་ཡིན།","ཁོ་དགེ་རྒན་ཡིན།"]),("copula","Identity statements","Use ཡིན for simple identity statements.",["ང་སློབ་མ་ཡིན།","འདི་དེབ་ཡིན།"]),("negation","Negation","Use མིན for basic negative identity statements.",["ང་དགེ་རྒན་མིན།","འདི་ཁང་པ་མིན།"]),("questions","Questions","Ask basic questions with ག་རེ and གང་དུ.",["འདི་ག་རེ་རེད།","ཁྱེད་རང་གང་དུ་ཡོད།"]),("demonstratives","Demonstratives","Use འདི and དེ for this and that.",["འདི་ཁང་པ་རེད།","དེ་སློབ་གྲྭ་རེད།"]),("numbers","Numbers","Use simple numbers with familiar objects.",["དེབ་གཉིས་ཡོད།","མི་གསུམ་ཡོད།"]),("location","Location","Use ནང་དུ and ལ་ཡོད for basic locations.",["ང་ཁང་པའི་ནང་དུ་ཡོད།","སློབ་གྲྭ་འདིར་ཡོད།"]),("time","Time expressions","Talk about today and tomorrow.",["དེ་རིང་ང་ལས་ཀ་བྱེད།","སང་ཉིན་ང་སློབ་གྲྭར་འགྲོ།"])]]
