PHRASEBOOK_CATEGORIES=[p(*x) for x in [("greetings_a1","Greetings",[("བཀྲ་ཤིས་བདེ་ལེགས།","greeting"),("ཁྱེད་རང་གི་མིང་ལ་ག་རེ་ཟེར།","asking a name"),("ངའི་མིང་ལ་བཀྲ་ཤིས་ཟེར།","introducing yourself")]),("thanks_a1","Thanks",[("ཐུགས་རྗེ་ཆེ།","saying thank you"),("ཐུགས་རྗེ་ཆེ་ཞེས་གསུང་རོགས།","polite thanks"),("དགའ་བསུ་ཡིན།","responding politely")]),("shopping_a1","Shopping",[("རིན་གོང་ག་ཚོད་རེད།","asking price"),("འདི་དགོས།","requesting an item"),("འདི་ག་ཚོད་རེད།","asking the cost")]),("directions_a1","Directions",[("སློབ་གྲྭ་གང་དུ་ཡོད།","asking location"),("གཡས་ཕྱོགས་སུ་འགྲོ།","giving directions"),("གཡོན་ཕྱོགས་སུ་འགྲོ།","giving another direction")]),("help_a1","Help",[("རོགས་རམ་གནང་རོགས།","asking for help"),("ངས་ཧ་མི་གོ།","saying you do not understand"),("ཡང་བསྐྱར་གསུང་རོགས།","asking someone to repeat")])]]
