ASSESSMENT_BANK=[AssessmentQuestion(id=f"bo-a1-{i:03}",skill=s,difficulty="A1",question=q,options=o,correct=c) for i,(s,q,o,c) in enumerate([("vocabulary","You meet someone for the first time. Which Tibetan greeting should you use?",["བཀྲ་ཤིས་བདེ་ལེགས།","ཐུགས་རྗེ་ཆེ།","ཆུ","སློབ་གྲྭ"],"hello"),("grammar","You want to say “I am not a teacher.” Which Tibetan sentence is correct?",["ང་དགེ་རྒན་མིན།","ང་དགེ་རྒན་ཡིན།","ང་སློབ་མ་ཡིན།","ཁོ་དགེ་རྒན་ཡིན།"],"ང་དགེ་རྒན་མིན།"),("vocabulary","You are talking about your mother. Which Tibetan word should you use?",["ཨ་མ","ཨ་ཕ","གྲོགས་པོ","སློབ་གྲྭ"],"mother"),("grammar","You point to an unfamiliar object. Which Tibetan question should you use?",["འདི་ག་རེ་རེད།","ཁྱེད་རང་གང་དུ་ཡོད།","རིན་གོང་ག་ཚོད་རེད།","བཀྲ་ཤིས་བདེ་ལེགས།"],"འདི་ག་རེ་རེད།"),("vocabulary","You need water. Which Tibetan word means “water”?",["ཆུ","མར","ཇ","རིན་གོང"],"water"),("reading","དེབ་ཅོག་ཙེའི་སྟེང་དུ་ཡོད། You read the sentence above. Where is the book?",["ཅོག་ཙེའི་སྟེང་དུ","སློབ་གྲྭར","ཚོང་ཁང་དུ","ཁང་པའི་ནང་དུ"],"On the table"),("communication","You need help from someone nearby. Which Tibetan phrase should you use?",["རོགས་རམ་གནང་རོགས།","ཐུགས་རྗེ་ཆེ།","ད་ལྟའི་བར་དུ།","བཀྲ་ཤིས་བདེ་ལེགས།"],"རོགས་རམ་གནང་རོགས།"),("vocabulary","You are making plans for the next day. Which Tibetan word means “tomorrow”?",["སང་ཉིན","དེ་རིང","ཞོགས་པ","གཡས"],"tomorrow"),("grammar","You want to tell someone that you are at home. Which Tibetan sentence is correct?",["ང་ཁང་པའི་ནང་དུ་ཡོད།","ང་སློབ་གྲྭར་འགྲོ།","ངས་ཧ་མི་གོ།","ཁོ་དགེ་རྒན་ཡིན།"],"ང་ཁང་པའི་ནང་དུ་ཡོད།"),("communication","You did not understand what someone said. Which Tibetan phrase should you use?",["ངས་ཧ་མི་གོ།","ཐུགས་རྗེ་ཆེ།","བཀྲ་ཤིས་བདེ་ལེགས།","ད་ལྟའི་བར་དུ།"],"ངས་ཧ་མི་གོ།")],1)]
